#include <iostream>
#include <iomanip>
#include <array>

struct BitCard {
    unsigned face : 4;  // 0-12 (King)
    unsigned suit : 2;  // 0-3 (Diamonds, Hearts, Clubs, Spades)
    unsigned color : 1; // 0 (Black), 1 (Red)
};

struct AlignedExample {
    unsigned a : 13;
    unsigned   : 0;   // Force alignment to next storage boundary
    unsigned b : 4;
};

int main() {
    BitCard card1{12, 3, 0}; // King of Spades, Black
    BitCard card2{0, 1, 1};  // Ace of Hearts, Red

    std::cout << "Card 1 - Face: " << std::setw(2) << card1.face
              << " | Suit: " << std::setw(2) << card1.suit
              << " | Color: " << std::setw(2) << card1.color << '\n';

    std::cout << "Card 2 - Face: " << std::setw(2) << card2.face
              << " | Suit: " << std::setw(2) << card2.suit
              << " | Color: " << std::setw(2) << card2.color << '\n';

    std::cout << "sizeof(BitCard): " << sizeof(BitCard) << " bytes\n";
    std::cout << "sizeof(AlignedExample): " << sizeof(AlignedExample) << " bytes\n";
    return 0;
}

#include <iostream>
#include <cctype>

void inspectChar(char ch) {
    unsigned char uc = static_cast<unsigned char>(ch);
    std::cout << "Character: '" << ch << "' (ASCII " << static_cast<int>(uc) << ")\n";
    std::cout << "  isdigit : " << (std::isdigit(uc) ? "yes" : "no") << "\n";
    std::cout << "  isalpha : " << (std::isalpha(uc) ? "yes" : "no") << "\n";
    std::cout << "  isalnum : " << (std::isalnum(uc) ? "yes" : "no") << "\n";
    std::cout << "  isxdigit: " << (std::isxdigit(uc) ? "yes" : "no") << "\n";
    std::cout << "  isspace : " << (std::isspace(uc) ? "yes" : "no") << "\n";
    std::cout << "  ispunct : " << (std::ispunct(uc) ? "yes" : "no") << "\n";
    std::cout << "  toupper : '" << static_cast<char>(std::toupper(uc)) << "'\n";
}

int main() {
    inspectChar('8');
    inspectChar('f');
    inspectChar('#');
    return 0;
}
